import{_ as n,C as r,o as t,c as o,a2 as a,b as h,w as s,a as l,E as d,a3 as p}from"./chunks/framework.Ci_RTJJ5.js";const f=JSON.parse('{"title":"10 — Overview","description":"","frontmatter":{},"headers":[],"relativePath":"chapters/11-subagent/overview.md","filePath":"chapters/11-subagent/overview.md"}'),c={name:"chapters/11-subagent/overview.md"};function u(m,e,g,k,b,y){const i=r("Mermaid");return t(),o("div",null,[e[1]||(e[1]=a(`<h1 id="_10-—-overview" tabindex="-1">10 — Overview <a class="header-anchor" href="#_10-—-overview" aria-label="Permalink to &quot;10 — Overview&quot;">​</a></h1><p><em>How subagents work, and what isolation buys. Read this before you write code.</em></p><hr><h2 id="the-problem-a-child-solves" tabindex="-1">The problem a child solves <a class="header-anchor" href="#the-problem-a-child-solves" aria-label="Permalink to &quot;The problem a child solves&quot;">​</a></h2><p>A parent conversation has one budget and one purpose. A task like &quot;find every TODO and summarise them&quot; produces twenty file reads of detail, and none of it is useful to the parent once the summary exists. Left in the parent, it costs context for the rest of the session.</p><p>A subagent is a way to spend context in a place that gets thrown away:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  parent: &quot;summarise the TODOs&quot;  →  task(prompt)  →  [child: 20 reads]  →  &quot;3 TODOs, all in x&quot;</span></span>
<span class="line"><span>  parent history grows by:           one tool result</span></span></code></pre></div>`,7)),(t(),h(p,null,{default:s(()=>[d(i,{id:"mermaid-17",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20P%5B%22parent%20turn%22%5D%20--%3E%20T%5B%22task%20tool%22%5D%0A%20%20%20%20T%20--%3E%20C%5B%22child%20run%22%5D%0A%20%20%20%20C%20--%3E%20C1%5B%22child%20context%3A%3Cbr%2F%3Esystem%20%2B%20task%20prompt%22%5D%0A%20%20%20%20C1%20--%3E%20C2%5B%22read%2C%20read%2C%20read...%22%5D%0A%20%20%20%20C2%20--%3E%20C3%5B%22child%20answer%22%5D%0A%20%20%20%20C3%20--%3E%7C%22one%20tool%20result%22%7C%20P%0A%20%20%20%20C2%20-.-%3E%7C%2220%20messages%3Cbr%2F%3Enever%20reach%20the%20parent%22%7C%20X%5B%22discarded%22%5D%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a(`<p>The parent&#39;s history grows by one result. That is the entire economic argument.</p><h2 id="isolation-means-empty-not-inherited" tabindex="-1">Isolation means empty, not inherited <a class="header-anchor" href="#isolation-means-empty-not-inherited" aria-label="Permalink to &quot;Isolation means empty, not inherited&quot;">​</a></h2><p>The child starts from:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  [ system message, task prompt ]</span></span></code></pre></div><p>Not from the parent&#39;s history. Not from a summary of it. Two reasons:</p><ol><li><strong>Cost.</strong> Inheriting the parent&#39;s conversation makes the child as expensive as the parent, and the detail problem is unsolved.</li><li><strong>Clarity.</strong> A child told &quot;do this specific thing&quot; is easier to reason about than one that has read everything the parent has said.</li></ol><p>The consequence is a constraint on whoever writes the task prompt: <strong>the child cannot see the conversation.</strong> That is why the prompt has to be complete, and why the tool description says so. A model told to &quot;fix it&quot; without being told what &quot;it&quot; is produces a confident wrong answer.</p><h2 id="recursion-is-prevented-by-the-registry-not-by-a-rule" tabindex="-1">Recursion is prevented by the registry, not by a rule <a class="header-anchor" href="#recursion-is-prevented-by-the-registry-not-by-a-rule" aria-label="Permalink to &quot;Recursion is prevented by the registry, not by a rule&quot;">​</a></h2><p>The dangerous version of this feature is a child that can spawn children. Two levels of fan-out turn one request into a tree, and the request count explodes before anyone notices.</p><p>There are two ways to prevent it:</p><table tabindex="0"><thead><tr><th>Approach</th><th>Behaviour</th></tr></thead><tbody><tr><td>a depth counter, checked at runtime</td><td>a bug in the check is a runaway</td></tr><tr><td>the tool is absent from the child&#39;s registry</td><td>impossible</td></tr></tbody></table><p>This chapter uses the second. The child&#39;s registry is built before the task tool exists:</p><div class="language-go vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">base </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> []</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Tool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{read, write, bash}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">child </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> NewRegistry</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(base</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)                       </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// no task</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">parent </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> NewRegistry</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">append</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(base, task)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// task, once</span></span></code></pre></div><p>The child still has real tools, because a subagent that cannot read a file cannot summarise a repository. The restriction is on delegation, not on work.</p><h2 id="one-call-one-result-every-time" tabindex="-1">One call, one result, every time <a class="header-anchor" href="#one-call-one-result-every-time" aria-label="Permalink to &quot;One call, one result, every time&quot;">​</a></h2><p>The parent is blocked inside a tool call. Whatever the child does, that call has to resolve:</p><table tabindex="0"><thead><tr><th>Child outcome</th><th>Parent receives</th></tr></thead><tbody><tr><td>answered</td><td>the answer text</td></tr><tr><td>hit its step cap</td><td>an error result naming the cap</td></tr><tr><td>provider failed</td><td>an error result naming the failure</td></tr><tr><td>returned empty</td><td>an error result</td></tr></tbody></table><p>An unresolved call is not a degraded conversation, it is an invalid one: providers reject a tool call with no result. So the failure path is part of the contract, not an afterthought.</p><p>Returning <code>(&quot;&quot;, err)</code> from <code>Execute</code> is enough, because <code>Registry.Run</code> already converts an error into an <code>IsError</code> result. Writing a success result <em>and</em> returning an error is how a call gets two results, which is the case <code>exactly-one-result</code> catches.</p><h2 id="the-parent-blocks-and-that-is-a-design-choice" tabindex="-1">The parent blocks, and that is a design choice <a class="header-anchor" href="#the-parent-blocks-and-that-is-a-design-choice" aria-label="Permalink to &quot;The parent blocks, and that is a design choice&quot;">​</a></h2><p>This chapter runs the child synchronously: the parent&#39;s turn waits.</p><p>The alternative is a background child that returns a receipt and delivers its answer later as a separate message. That is what real harnesses do for long jobs, and it is strictly harder:</p><ul><li>the result arrives when no call is waiting for it;</li><li>the parent needs a queue and an ordering rule;</li><li>an interrupted parent has a child that is still running.</li></ul><p>Sync first is the right order for learning. You cannot debug the async version without having seen the simple one.</p><h2 id="what-this-chapter-does-not-do" tabindex="-1">What this chapter does not do <a class="header-anchor" href="#what-this-chapter-does-not-do" aria-label="Permalink to &quot;What this chapter does not do&quot;">​</a></h2><ul><li><strong>No parallel children.</strong> One task call runs one child, in order. Two calls in one message run one after the other.</li><li><strong>No background delivery.</strong> The parent waits.</li><li><strong>No per-child model or budget.</strong> The child uses the same provider and the same context ceiling as the parent, with a smaller step cap.</li><li><strong>No child events.</strong> The child&#39;s turns emit into the same event stream, so a consumer sees a flat sequence with no indication of nesting.</li></ul><p>That last gap is honest and visible: the event stream from a parent with a child looks like one long run.</p><h2 id="where-the-real-implementations-go-further" tabindex="-1">Where the real implementations go further <a class="header-anchor" href="#where-the-real-implementations-go-further" aria-label="Permalink to &quot;Where the real implementations go further&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concern</th><th>Implementation</th></tr></thead><tbody><tr><td>Background children with receipts</td><td>pi subagent extensions</td></tr><tr><td>Fan-out limits and scheduling</td><td>pi-subagent-manager</td></tr><tr><td>Inherited context, as an opt-in</td><td>some extensions, via a transcript prefix</td></tr><tr><td>Depth limits when the registry is shared</td><td>depth counters in the loop</td></tr></tbody></table><p>One warning from the survey: an extension advertising &quot;inherit context&quot; may only prefix the child&#39;s prompt with a text transcript, which is not the same as a session fork. If you build that later, decide which one you mean.</p><h2 id="self-check" tabindex="-1">Self-check <a class="header-anchor" href="#self-check" aria-label="Permalink to &quot;Self-check&quot;">​</a></h2><ol><li>What does the parent&#39;s history grow by, and what does that buy? <em>(The problem a child solves)</em></li><li>Why does the child start empty rather than inheriting a summary? <em>(Isolation means empty, not inherited)</em></li><li>How is recursion prevented, and why is that better than a depth check? <em>(Recursion is prevented by the registry, not by a rule)</em></li><li>Name four child outcomes and what the parent receives for each. <em>(One call, one result, every time)</em></li><li>Why is synchronous the right first version? <em>(The parent blocks, and that is a design choice)</em></li></ol>`,32))])}const w=n(c,[["render",u]]);export{f as __pageData,w as default};
